    def run(self, n, start, requests):
        if len(requests)>12:
            raise ValueError('Visual request limit: 12 / Tối đa 12 yêu cầu.')
        full=(1<<len(requests))-1
        mask=sum(1<<i for i,(arrival,floor) in enumerate(requests) if arrival==0 and floor==start)
        heap=[(0,start,mask)]
        distance={(start,mask):0}
        while heap:
            time,position,mask=heappop(heap)
            if time!=distance[(position,mask)]:
                continue
            if mask==full:
                return time
            for i,(arrival,floor) in enumerate(requests):
                if mask>>i&1:
                    continue
                finish=max(time+abs(floor-position),arrival)
                next_mask=mask
                for j,(release,target) in enumerate(requests):
                    if min(position,floor)<=target<=max(position,floor) and release<=time+abs(target-position) or target==floor and release<=finish:
                        next_mask|=1<<j
                state=(floor,next_mask)
                if finish<distance.get(state,inf):
                    distance[state]=finish
                    heappush(heap,(finish,floor,next_mask))
        return -1

