    def maxValidSplits(self, nums):
        n = len(nums)

        def calc(arr):
            m = len(arr)
            pre = [0] * m
            suf = [0] * m
            pre[0] = arr[0]
            for i in range(1, m):
                pre[i] = gcd(pre[i - 1], arr[i])
            suf[-1] = arr[-1]
            for i in range(m - 2, -1, -1):
