            ans = 0
            for i in range(m - 1):
                if pre[i] == suf[i + 1]:
                    ans += 1
            return ans

        def mark(arr):
            pos = [False] * n
            pos[0] = True
            g = arr[0]
            for i in range(1, n):
                ng = gcd(g, arr[i])
                pos[i] = ng != g
                g = ng
            return pos
        pos1 = mark(nums)
        pos2 = mark(nums[::-1])
        ans = calc(nums)
