            branches=[visit(child) for child in children[node].values()]
            ranks=[rank for values,cost in branches for rank in values]
            base=sum(cost for values,cost in branches)
            if terminal[node] is not None:
                base+=sum(rank<terminal[node] for rank in ranks)
            count=len(branches)
            cross=[[sum(a>b for a in branches[i][0] for b in branches[j][0]) for j in range(count)] for i in range(count)]
            dp=[inf]*(1<<count)
            dp[0]=0
            for mask in range(1<<count):
                for next_child in range(count):
                    if not mask>>next_child&1:
                        extra=sum(cross[i][next_child] for i in range(count) if mask>>i&1)
                        dp[mask|1<<next_child]=min(dp[mask|1<<next_child],dp[mask]+extra)
            if terminal[node] is not None:
                ranks.append(terminal[node])
            return ranks,base+dp[-1]
        return visit(0)[1]

