            if i + 1 < len(nums):
                s = x + nums[i + 1]
                t = s - dfs(i + 2) if s % 3 == 0 else s + dfs(i + 2)
                res = max(res, t)
            return res
        return dfs(0)

class Solution:

    def countConsistent(self, nums):
        n = len(nums)
        left = [-1] * n
        stk = []
        for i, x in enumerate(nums):
            while stk and nums[stk[-1]] & x == x:
                stk.pop()
            if stk:
                left[i] = stk[-1]
            stk.append(i)
        stk = []
        ans = 0
        for i in range(n - 1, -1, -1):
            x = nums[i]
            while stk and nums[stk[-1]] != x and (nums[stk[-1]] & x == x):
                stk.pop()
            right = stk[-1] if stk else n
            stk.append(i)
            ans += (i - left[i]) * (right - i)
        return ans

class Solution:

    def sumOfGoodIntegers(self, n, k):

        @cache
        def dfs(i, lim):
            if i < 0:
                return (1, 0)
            up = num >> i & 1 if lim else 1
            cnt = s = 0
            for cur in range(up + 1):
                if n >> i & 1 == 1 and cur == 1:
                    continue
                cnt1, s1 = dfs(i - 1, lim and cur == up)
                cnt += cnt1
                s += s1 + cnt1 * (cur << i) % mod
            return (cnt, s % mod)
        mod = 10 ** 9 + 7
        lo, hi = (max(1, n - k), n + k)
        m = hi.bit_length()
        num = hi
        right = dfs(m - 1, True)[1]
        dfs.cache_clear()
        num = lo - 1
        left = dfs(m - 1, True)[1]
        dfs.cache_clear()
        return (right - left + mod) % mod

class Solution:

    def assignUmbrella(self, rain):
        n = len(rain)
        a = b = 0
        ans = [None] * n
        for i, x in enumerate(rain):
            if x == 0:
                ans[i] = 'None'
            elif a <= b and i < n - 1 and (rain[i + 1] == 1):
                ans[i] = 'Alice'
                a += 1
            else:
                ans[i] = 'Bob'
                b += 1
        return ans

class Solution:

    def minRange(self, a, b, c):
