        nums.sort()
        return min(nums[2] - nums[0], nums[1])

class Solution:
    def run(self, nums):
        n=len(nums)
        if n<3:
            return -1
        height=max(nums)+n
        if n>30 or height>160:
            raise ValueError('Visual mountain limit: 30 values, height <=160 / Tối đa 30 số, chiều cao <=160.')
        def rising(values):
            rows=[]
            previous=[0]+[inf]*height
            for value in values:
                best=inf
                current=[inf]*(height+1)
                for h in range(1,height+1):
                    best=min(best,previous[h-1])
                    current[h]=best+abs(value-h)
                rows.append(current)
                previous=current
            return rows
        left=rising(nums)
        right=rising(nums[::-1])[::-1]
        answer=inf
        for peak in range(1,n-1):
            for h in range(1,height+1):
                answer=min(answer,left[peak][h]+right[peak][h]-abs(nums[peak]-h))
        return answer

class Solution:
    def run(self, nums, k):
        windows=[]
        for left in range(len(nums)-k+1):
            mask=nums[left]
            for value in nums[left+1:left+k]:
                mask&=value
            if mask==0:
                return -1
            windows.append(mask)
        constraints=tuple(sorted(set(windows)))
        @cache
        def cover(remaining):
            if not remaining:
                return 0
            mask=min(remaining,key=int.bit_count)
            best=inf
            while mask:
                bit=mask&-mask
                best=min(best,1+cover(tuple(value for value in remaining if not value&bit)))
                mask-=bit
            return best
        return cover(constraints)

class Solution:

    def countDominantElements(self, nums):
        ans = 0
        for i, x in enumerate(nums):
            s = cnt = 0
            if i > 0:
                s += nums[i - 1]
                cnt += 1
            if i < len(nums) - 1:
                s += nums[i + 1]
                cnt += 1
            if cnt == 0 or x >= s / cnt:
                ans += 1
        return ans

class Solution:

    def minCost(self, nums):
        n = len(nums)
        ans = inf
        l = 0
        for r, x in enumerate(nums):
            if r == n - 1 or x != nums[r + 1]:
                if r > 0 and l < n - 1:
                    ans = min(ans, (l + n - r - 1) * x)
                l = r + 1
        return ans

class Solution:
    def run(self, n, edges, requiredSignals):
        graph=[[] for _ in range(n)]
        for u,v,delay in edges:
            graph[u].append((v,delay))
        answer=[-1]*n
        seen=[set() for _ in range(n)]
        heap=[]
        for node in range(n):
            if node==0 or requiredSignals[node]==0:
                answer[node]=0
                for child,delay in graph[node]:
                    heappush(heap,(delay,node,child))
        while heap:
            time,source,node=heappop(heap)
            if answer[node]!=-1 or source in seen[node]:
                continue
            seen[node].add(source)
            if len(seen[node])>=requiredSignals[node]:
                answer[node]=time
                for child,delay in graph[node]:
                    heappush(heap,(time+delay,node,child))
        return answer

class Solution:
    def run(self, nums):
        n=len(nums)
        if not 2<=n<=12:
            raise ValueError('Visual interval-DP limit: 2-12 values / Nhập từ 2 đến 12 số.')
        full=[[inf]*n for _ in nums]
        free=[[0]*n for _ in nums]
        for length in range(2,n+1):
            for left in range(n-length+1):
                right=left+length-1
                for end in range(left+1,right+1):
                    inside=free[left+1][end-1] if end>left+1 else 0
                    tail=full[end+1][right] if end<right else 0
                    full[left][right]=min(full[left][right],nums[left]+nums[end]+inside+tail)
                free[left][right]=free[left+1][right]
                for end in range(left+1,right+1):
                    tail=free[end+1][right] if end<right else 0
                    free[left][right]=min(free[left][right],full[left][end]+tail)
        return full[0][-1]
